fun groupByAlliance(teams: List<Pair<String, Int>>): Map<String, List<Int>> {
    val result = mutableMapOf<String, MutableList<Int>>()
    for ((alliance, number) in teams) {
        if (alliance !in result) {
            result[alliance] = mutableListOf()
        }
        result[alliance]!!.add(number)
    }
    return result
}

