import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testTwoAlliances() {
        val result = groupByAlliance(listOf(
            "Red" to 4215,
            "Blue" to 1234,
            "Red" to 5678,
            "Blue" to 9999
        ))
        Assert.assertEquals(listOf(4215, 5678), result["Red"])
        Assert.assertEquals(listOf(1234, 9999), result["Blue"])
    }

    @Test
    fun testSingleAlliance() {
        val result = groupByAlliance(listOf(
            "Red" to 4215,
            "Red" to 1234
        ))
        Assert.assertEquals(listOf(4215, 1234), result["Red"])
        Assert.assertNull(result["Blue"])
    }

    @Test
    fun testEmptyList() {
        val result = groupByAlliance(listOf())
        Assert.assertTrue(result.isEmpty())
    }

    @Test
    fun testThreeTeamsPerAlliance() {
        val result = groupByAlliance(listOf(
            "Red" to 4215,
            "Red" to 1234,
            "Red" to 5678,
            "Blue" to 9999,
            "Blue" to 7777,
            "Blue" to 3333
        ))
        Assert.assertEquals(3, result["Red"]!!.size)
        Assert.assertEquals(3, result["Blue"]!!.size)
    }
}
